/* ATLAS 2.1 — browser planner; source is intentionally dependency-free except optional map/3D libs. */
(()=>{'use strict';
const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>Array.from(r.querySelectorAll(q));
const KEY='arielbodik.atlas.trip.v2', MAX_DAYS=60;
const moneySymbols={USD:'$',EUR:'€',GBP:'£',JPY:'¥',CAD:'C$',AUD:'A$'};
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const iso=s=>new Date(`${s}T12:00:00Z`);
const dateAdd=(s,n)=>{const d=iso(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const dateDiff=(a,b)=>Math.round((iso(b)-iso(a))/86400000);
const dateValid=s=>/^\d{4}-\d\d-\d\d$/.test(s)&&!Number.isNaN(iso(s).valueOf())&&iso(s).toISOString().slice(0,10)===s;
const dateLabel=(s,weekday=true)=>new Date(`${s}T12:00:00Z`).toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric',...(weekday?{weekday:'short'}:{})});
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
const clamp=(v,min,max)=>Math.min(max,Math.max(min,Number(v)||0));
const plain=(s,max=100)=>String(s||'').slice(0,max);
const stop=(name,lat,lng,time='09:00',category='sight',duration=75,cost=0,notes='')=>({id:uid(),name,lat,lng,time,category,duration,cost,notes,source:'sample',sourceUrl:'',estimate:true});
const defaults=(names)=>names.map(name=>({id:uid(),name,done:false}));
const PACKING=['Passport or ID','Tickets and reservations (offline copy)','Phone and charging cable','Adapters and power bank','Weather-appropriate clothes','Comfortable walking shoes','Prescriptions and medications','Toiletries and sunscreen','Backup payment method'];
const READINESS=['Check official entry, visa and passport rules','Review official travel advisories','Confirm hotel cancellation and check-in details','Confirm flight baggage policy and transfers','Check local transport routes and operating hours','Check medical and travel insurance coverage','Save important bookings offline','Share itinerary with an emergency contact'];
function demo(){const start='2027-04-02';return {version:3,title:'Spring days in Kyoto',destination:{name:'Kyoto, Japan',lat:35.0116,lng:135.7681},start,end:dateAdd(start,4),travelers:2,pace:'balanced',currency:'USD',budget:3000,activeDay:0,isDemo:true,days:[
[stop('Fushimi Inari Taisha',34.9671,135.7727,'08:30','sight',95,0,'Arrive early; actual opening hours and access vary.'),stop('Nishiki Market',35.005,135.765,'12:30','food',70,25),stop('Gion district',35.0033,135.7783,'16:00','sight',100,0)],
[stop('Kiyomizu-dera',34.995,135.785,'09:00','sight',100,9),stop('Sannenzaka',34.9964,135.7827,'12:30','sight',80,20)],
[stop('Arashiyama Bamboo Grove',35.0171,135.6713,'08:15','nature',80,0),stop('Tenryu-ji',35.0158,135.6739,'11:30','sight',85,12)],
[stop('Kinkaku-ji',35.0394,135.7292,'09:30','sight',90,10),stop('Nijo Castle',35.0142,135.7481,'13:30','sight',110,12)],
[stop("Philosopher's Path",35.0242,135.7935,'09:00','nature',90,0),stop('Kyoto Station',34.9855,135.7585,'15:00','other',60,0)]
].map((stops,i)=>({id:uid(),date:dateAdd(start,i),label:'',stops})),expenses:[],quotes:[],packing:defaults(PACKING),readiness:defaults(READINESS)};}
function normalize(raw){if(!raw||typeof raw!=='object')throw Error('Invalid trip file.');const base=demo();const start=dateValid(raw.start)?raw.start:base.start,end=dateValid(raw.end)?raw.end:base.end;const n=dateDiff(start,end);if(n<0||n>=MAX_DAYS)throw Error('Trip must last 1–60 days.');
const dest=raw.destination||base.destination;const validCoord=(a,b)=>Number.isFinite(Number(a))&&Number.isFinite(Number(b))&&Math.abs(Number(a))<=90&&Math.abs(Number(b))<=180;let days=Array.from({length:n+1},(_,i)=>{const src=raw.days?.[i]||{},stops=(Array.isArray(src.stops)?src.stops:[]).slice(0,70).filter(s=>validCoord(s.lat,s.lng)).map(s=>({id:plain(s.id,90)||uid(),name:plain(s.name,110)||'Stop',lat:Number(s.lat),lng:Number(s.lng),time:/^([01]\d|2[0-3]):[0-5]\d$/.test(s.time)?s.time:'09:00',category:plain(s.category,20)||'other',duration:clamp(s.duration||75,15,720),cost:clamp(s.cost,0,1e7),notes:plain(s.notes,1500),source:plain(s.source,60)||'manual',sourceUrl:safeURL(s.sourceUrl),image:safeURL(s.image),creditUrl:safeURL(s.creditUrl),attribution:plain(s.attribution,140),license:plain(s.license,70),estimate:!!(s.estimate??s.demoEstimate)}));return {id:plain(src.id,80)||uid(),date:dateAdd(start,i),label:plain(src.label,90),stops}});
const list=(v,d)=>(Array.isArray(v)?v:defaults(d)).slice(0,200).map(e=>({id:plain(e.id,90)||uid(),name:plain(e.name,140)||'Item',done:!!e.done}));return {version:3,title:plain(raw.title,80)||base.title,destination:validCoord(dest.lat,dest.lng)?{name:plain(dest.name,130)||'Destination',lat:Number(dest.lat),lng:Number(dest.lng)}:base.destination,start,end,travelers:clamp(raw.travelers||2,1,25),pace:['relaxed','balanced','packed'].includes(raw.pace)?raw.pace:'balanced',currency:moneySymbols[raw.currency]?raw.currency:'USD',budget:clamp(raw.budget,0,1e8),activeDay:clamp(raw.activeDay,0,n),isDemo:!!raw.isDemo,days,quotes:(Array.isArray(raw.quotes)?raw.quotes:[]).slice(0,80).map(q=>({id:plain(q.id,90)||uid(),provider:plain(q.provider,55),title:plain(q.title,90),price:clamp(q.price,0,1e8),terms:plain(q.terms,160),url:safeURL(q.url),date:plain(q.date,16)})),expenses:(Array.isArray(raw.expenses)?raw.expenses:[]).slice(0,200).map(e=>({id:plain(e.id,90)||uid(),name:plain(e.name,90),category:plain(e.category,24)||'Other',amount:clamp(e.amount,0,1e7)})),packing:list(raw.packing,PACKING),readiness:list(raw.readiness,READINESS)};}
let trip;try{trip=normalize(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{trip=demo()}
let discoveryUnit='mi', discoveryRadiusKm=40.2336, discoveryCategory='all', discoveryPage=0, discoveryBusy=false, discoveryHasMore=false, discoveryProvider='';
const OPTION_KEY='arielbodik.atlas.trip.options.v1';
let savedOptions=[];try{savedOptions=JSON.parse(localStorage.getItem(OPTION_KEY)||'[]');if(!Array.isArray(savedOptions))savedOptions=[];}catch{savedOptions=[];}
function optionsStore(){try{localStorage.setItem(OPTION_KEY,JSON.stringify(savedOptions.slice(0,25)))}catch{toast('Could not save trip alternatives; export your trip for safety.')}}
function totalOf(t){return (t.days||[]).flatMap(d=>d.stops||[]).reduce((v,x)=>v+(Number(x.cost)||0),0)+(t.expenses||[]).reduce((v,x)=>v+(Number(x.amount)||0),0)}
function renderOptionLab(){const el=$('#atlas-option-list');if(!el)return;const flexible=allStops().reduce((n,p)=>n+(Number(p.cost)||0),0),fixed=trip.expenses.reduce((n,p)=>n+(Number(p.amount)||0),0);$('#atlas-scenarios').innerHTML=[['Save',.85,'15% less in estimated activities'],['Balanced',1,'Current estimates'],['Treat',1.3,'30% more for estimated activities']].map(([name,factor,detail])=>`<div><small>${name}</small><strong>${esc(money(fixed+flexible*factor))}</strong><span>${esc(detail)}</span></div>`).join('');el.innerHTML=savedOptions.length?`<table class="atlas-options-table"><thead><tr><th>Saved trip option</th><th>Days</th><th>Stops</th><th>Tracked estimates</th><th>Actions</th></tr></thead><tbody>${savedOptions.map(x=>`<tr><td><strong>${esc(x.title)}</strong><small>${esc(x.destination||'')}</small></td><td>${Number(x.days)||1}</td><td>${Number(x.stops)||0}</td><td>${esc(money(Number(x.total)||0))}</td><td><button type="button" data-option-load="${esc(x.id)}">Load</button><button type="button" data-option-delete="${esc(x.id)}">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="atlas-no-options">No saved alternatives yet. Save your current trip or load a research idea to start comparing.</div>'}
function saveCurrentOption(){let title=prompt('Name this trip option',trip.title)||trip.title;if(!title.trim())return;const snap=JSON.parse(JSON.stringify(trip));savedOptions.unshift({id:uid(),title:plain(title,80),destination:trip.destination.name,days:trip.days.length,stops:allStops().length,total:totalOf(trip),snapshot:snap});savedOptions=savedOptions.slice(0,25);optionsStore();renderOptionLab();toast('Saved as a separate trip alternative on this device.');}
function loadSavedOption(id){const opt=savedOptions.find(x=>x.id===id);if(!opt)return;if(!confirm(`Load "${opt.title}"? Your current unsaved alternative will be replaced. Export current trip if needed.`))return;trip=normalize(opt.snapshot);ignoredMismatch=false;discovered=[];save();render();renderDiscovered();refreshGuide();refreshWeather();map?.flyTo({center:[trip.destination.lng,trip.destination.lat],zoom:10});toast('Loaded '+opt.title);}
async function loadResearchIdea(){const idx=Number($('#atlas-preset-select').value);if(!confirm('Load the research trip? Your current trip will be replaced. Prices and hours from the original file are not live confirmations.'))return;try{const r=await fetch('./assets/trip-ideas.json',{signal:AbortSignal.timeout(9000)});if(!r.ok)throw Error('Research ideas file is missing.');const data=await r.json();const item=data[idx];if(!item)throw Error('Trip idea not found.');trip=normalize(item);ignoredMismatch=false;discovered=[];save();render();renderDiscovered();refreshGuide();refreshWeather();map?.flyTo({center:[trip.destination.lng,trip.destination.lat],zoom:9});toast('Loaded '+trip.title+' · check times and prices before booking.');}catch(e){toast(e.message)}}
let ignoredMismatch=false;let currentView='overview', map=null, markers=[], mapReady=false, globe=null, globeBusy=false, mapMode='map', discovered=[], weatherData=null, guideData=null, chatHistory=[], chatProposals=[], activeBooking='stays',activeChecklist='packing',toastTimer=0,lastGeocode=0, pendingAuto=false;
const currentDay=()=>trip.days[trip.activeDay]||trip.days[0];const allStops=()=>trip.days.flatMap(d=>d.stops);const plannedTotal=()=>allStops().reduce((a,s)=>a+s.cost,0)+trip.expenses.reduce((a,e)=>a+e.amount,0);const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:trip.currency,maximumFractionDigits:trip.currency==='JPY'?0:2}).format(Number(n)||0);
function save(){try{localStorage.setItem(KEY,JSON.stringify(trip));$('#save-status').textContent='● Saved locally'}catch{$('#save-status').textContent='Export to save';}}
function toast(msg){const node=$('#toast');node.textContent=msg;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),3500)}
function openView(name){currentView=name;$$('.view').forEach(x=>x.classList.toggle('is-visible',x.id==='view-'+name));$$('[data-view]').forEach(x=>x.classList.toggle('is-active',x.dataset.view===name));$('#breadcrumb-page').textContent=name[0].toUpperCase()+name.slice(1);window.scrollTo?.({top:0,behavior:'smooth'});if(name==='overview')setTimeout(()=>{map?.resize();updateMap()},80);if(name==='bookings')renderBookings();}
function updateDays(start,end){const n=dateDiff(start,end);if(n<0||n>=MAX_DAYS)throw Error('Trips may be 1–60 days.');const old=trip.days;trip.start=start;trip.end=end;trip.days=Array.from({length:n+1},(_,i)=>({id:old[i]?.id||uid(),date:dateAdd(start,i),label:old[i]?.label||'',stops:old[i]?.stops||[]}));trip.activeDay=Math.min(trip.activeDay,n);trip.isDemo=false;save();render();}
function updateDate(kind,newValue){if(!dateValid(newValue)){toast('Choose a valid date.');renderBasics();return;}try{const originalLength=dateDiff(trip.start,trip.end);if(kind==='start'){
// Preserve the trip's duration and retain each day's stops when moving departure.
const futureEnd=dateAdd(newValue,Math.max(0,originalLength));updateDays(newValue,futureEnd);
}else{
// Return can be set freely. If it is before departure, shift departure to return (one-day trip).
const newStart=newValue<trip.start?newValue:trip.start;const futureDays=dateDiff(newStart,newValue)+1;
if(futureDays<trip.days.length&&trip.days.slice(futureDays).some(d=>d.stops.length)&&!confirm('Shortening this trip removes the activities on deleted days. Export first to keep a backup. Continue?')){renderBasics();return;}updateDays(newStart,newValue);
}toast('Dates updated · '+trip.days.length+' days');}catch(e){toast(e.message);renderBasics();}}
const haversine=(a,b)=>{const r=Math.PI/180,la1=Number(a.lat)*r,la2=Number(b.lat)*r,dLat=la2-la1,dLng=(Number(b.lng)-Number(a.lng))*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dLat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dLng/2)**2));};
function renderMismatch(){const stops=allStops(),far=stops.filter(s=>haversine(trip.destination,s)>250);const mismatch=stops.length>=2&&far.length/stops.length>.65&&!ignoredMismatch;$('#location-warning').hidden=!mismatch;if(!mismatch)return;const kyoto=stops.some(s=>/Fushimi Inari|Kiyomizu-dera|Arashiyama/i.test(s.name));$('#location-warning-title').textContent='The destination and itinerary stops may be in different regions.';$('#location-warning-text').textContent=`${far.length} of ${stops.length} stops are over 250 km from ${trip.destination.name}. ${kyoto?'These appear to be sample Kyoto activities.':'Confirm whether this is a multi-city trip.'}`;$('#location-warning-fix').textContent=kyoto?'Set destination to Kyoto':'Clear distant activities';$('#location-warning-fix').dataset.fix=kyoto?'kyoto':'clear';}
function renderBasics(){const set=(id,val)=>{const el=$('#'+id);if(el&&el.value!==String(val))el.value=val};set('start-date',trip.start);set('end-date',trip.end);set('traveler-count',trip.travelers);set('currency-select',trip.currency);set('budget-input',trip.budget);
$('#start-date').removeAttribute('max');$('#end-date').min=trip.start;$('#end-date').max=dateAdd(trip.start,MAX_DAYS-1);
$('#side-trip-name').textContent=trip.title;$('#side-trip-detail').textContent=trip.destination.name+' · '+trip.days.length+' days';$('#sidebar-day-count').textContent=trip.days.length;
$('#trip-date-summary').textContent=`${dateLabel(trip.start,false)} – ${dateLabel(trip.end,false)} · ${trip.days.length} days`;
$('#trip-destination-summary').textContent=trip.destination.name;
$('#destination-input').placeholder=trip.destination.name||'City or country';$('#map-title').textContent=trip.destination.name;
$$('[data-pace]').forEach(x=>x.classList.toggle('is-active',x.dataset.pace===trip.pace));
$('#booking-context').textContent=`${trip.destination.name} · ${dateLabel(trip.start,false)}–${dateLabel(trip.end,false)} · ${trip.travelers} traveler${trip.travelers===1?'':'s'}. Confirm details at provider checkout.`;}
function renderPills(elId){$(elId).innerHTML=trip.days.map((d,i)=>`<button class="${i===trip.activeDay?'is-active':''}" data-day="${i}">Day ${i+1} · ${esc(dateLabel(d.date,false))}</button>`).join('');}
function dayTotals(d){return d.stops.reduce((n,s)=>n+s.cost,0)}
function renderOverview(){renderPills('#overview-day-pills');const day=currentDay();$('#overview-itinerary-title').textContent='Day '+(trip.activeDay+1)+' · '+dateLabel(day.date);
$('#overview-timeline').innerHTML=day.stops.length?day.stops.map((s,i)=>`<div class="timeline-row"><span class="time-chip">${esc(s.time)}</span><span class="timeline-index">${i+1}</span><span class="timeline-detail"><strong>${esc(s.name)}</strong><small>${esc(s.duration)} min · ${esc(money(s.cost))} ${s.estimate?'· sample estimate':''}</small></span></div>`).join(''):'<div class="empty-state">A fresh page for Day '+(trip.activeDay+1)+'. Add places or ask ATLAS AI to suggest a day plan.</div>';
$('#quick-budget').textContent=`${money(plannedTotal())} of ${money(trip.budget)}`;$('#quick-budget-detail').textContent=`${money(Math.max(0,trip.budget-plannedTotal()))} left within your planning target.`;
if(!weatherData){$('#quick-weather').textContent='Weather, when it matters';$('#quick-weather-detail').textContent='Fetch current conditions; far-off trip dates are not forecastable.';}}
function directionsLink(d){const stops=d.stops;if(stops.length<2)return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(trip.destination.name)}`;const origin=`${stops[0].lat},${stops[0].lng}`,destination=`${stops.at(-1).lat},${stops.at(-1).lng}`,mid=stops.slice(1,-1).map(x=>`${x.lat},${x.lng}`).join('|');return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(origin)+'&destination='+encodeURIComponent(destination)+(mid?'&waypoints='+encodeURIComponent(mid):'')+'&travelmode=walking';}
function renderItinerary(){renderPills('#itinerary-day-selector');const d=currentDay();$('#selected-day-title').textContent=`Day ${trip.activeDay+1} · ${dateLabel(d.date)}`;$('#day-directions').href=directionsLink(d);
$('#itinerary-stops').innerHTML=d.stops.length?d.stops.map((s,i)=>`<div class="stop-row"><span class="stop-time">${esc(s.time)}</span><span class="timeline-index">${i+1}</span><div class="stop-main">${s.image?`<img loading="lazy" class="atlas-stop-photo" src="${esc(safeURL(s.image))}" alt="Source photo for ${esc(s.name)}" />`:``}<strong>${esc(s.name)}</strong><small>${s.duration} min · ${esc(money(s.cost))} ${s.notes?'· '+esc(s.notes).slice(0,55):''}</small></div><div class="stop-controls"><button data-stop-action="edit" data-stop-id="${esc(s.id)}" aria-label="Edit ${esc(s.name)}">✎</button><button data-stop-action="up" data-stop-id="${esc(s.id)}" title="Move up">↑</button><button data-stop-action="down" data-stop-id="${esc(s.id)}" title="Move down">↓</button><button data-stop-action="delete" data-stop-id="${esc(s.id)}" title="Delete stop">×</button></div></div>`).join(''):'<div class="empty-state">No activities here yet. Add a stop or ask your AI copilot to help.</div>';
$('#day-cost-total').textContent=money(dayTotals(d));const mins=d.stops.reduce((a,s)=>a+s.duration,0);$('#day-pacing-note').textContent=d.stops.length?`${d.stops.length} stops · ${Math.round(mins/60*10)/10} hours on-site, excluding transit and queues. ${mins>420?'This is an ambitious day—consider travel time and breaks.':'Keep some flexibility for meals, transfers and opening hours.'}`:'Add your first activity. Travel time and business hours should be confirmed separately.';}
function renderBudget(){const spent=plannedTotal();$('#expense-total').textContent=money(spent);$('#budget-symbol').textContent=moneySymbols[trip.currency];$('#budget-progress').style.width=(trip.budget?Math.min(100,spent/trip.budget*100):0)+'%';$('#budget-progress').style.background=spent>trip.budget?'#c96b59':'#45ab88';$('#budget-remaining').textContent=spent>trip.budget?money(spent-trip.budget)+' over your budget target':money(trip.budget-spent)+' available in your plan';$('#expense-items').innerHTML=trip.expenses.length?trip.expenses.map(e=>`<div class="expense-item"><span>${esc(e.name)} · ${esc(e.category)}</span><strong>${esc(money(e.amount))} <button data-remove-expense="${esc(e.id)}" aria-label="Remove">×</button></strong></div>`).join(''):'<p class="muted-text">Add flights, lodging, and other estimated costs here.</p>';}
function renderChecklist(){const entries=trip[activeChecklist]||[],done=entries.filter(e=>e.done).length;$('#check-progress').textContent=`${done} of ${entries.length} completed`;
$('#checklist-items').innerHTML=entries.map(e=>`<div class="check-item ${e.done?'is-done':''}"><input type="checkbox" data-check="${esc(e.id)}" id="check-${esc(e.id)}" ${e.done?'checked':''}><label for="check-${esc(e.id)}">${esc(e.name)}</label><button data-delete-check="${esc(e.id)}" aria-label="Delete">×</button></div>`).join('');$$('[data-checklist]').forEach(b=>b.classList.toggle('is-active',b.dataset.checklist===activeChecklist));}
function render(){renderOptionLab();renderBasics();renderMismatch();renderOverview();renderItinerary();renderBudget();renderChecklist();renderBookings();renderQuotes();renderSources();updateMap();globe?.update(trip);}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog-backdrop').hidden=false;$('#dialog-content input')?.focus();}
function closeDialog(){$('#dialog-backdrop').hidden=true;$('#dialog-content').innerHTML='';}
function editTripName(){dialog('Name your journey',`<form id="name-form"><label>Trip name<input name="title" value="${esc(trip.title)}" maxlength="80" required></label><button class="btn btn-dark" type="submit">Save trip name</button></form>`);}
function editStop(id){const existing=currentDay().stops.find(x=>x.id===id),s=existing||{name:'',lat:trip.destination.lat,lng:trip.destination.lng,time:'09:00',duration:75,cost:0,category:'other',notes:''};dialog(existing?'Edit activity':'Add activity',`<form id="stop-form"><label>Place or activity<input name="name" value="${esc(s.name)}" required maxlength="110" placeholder="e.g. Kyoto Railway Museum"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label>Time<input name="time" type="time" value="${esc(s.time)}" required></label><label>Minutes<input name="duration" type="number" min="15" max="720" value="${s.duration}" required></label><label>Cost estimate (${esc(trip.currency)})<input name="cost" type="number" min="0" step="0.01" value="${s.cost}"></label><label>Category<select name="category">${['sight','nature','food','stay','other'].map(c=>`<option value="${c}" ${s.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Latitude<input name="lat" type="number" step="any" min="-90" max="90" value="${s.lat}" required></label><label>Longitude<input name="lng" type="number" step="any" min="-180" max="180" value="${s.lng}" required></label></div><label>Notes<textarea name="notes" maxlength="1500">${esc(s.notes)}</textarea></label><button class="btn btn-dark" type="submit">${existing?'Save activity':'Add to Day '+(trip.activeDay+1)}</button></form>`);$('#stop-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget), lat=Number(fd.get('lat')),lng=Number(fd.get('lng'));if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){toast('Enter valid coordinates.');return;}const updated={id:existing?.id||uid(),name:plain(fd.get('name'),110),time:String(fd.get('time')),duration:clamp(fd.get('duration'),15,720),cost:clamp(fd.get('cost'),0,1e7),category:String(fd.get('category')),lat,lng,notes:plain(fd.get('notes'),1500),source:existing?.source||'manual',sourceUrl:existing?.sourceUrl||'',estimate:false};if(existing){Object.assign(existing,updated)}else currentDay().stops.push(updated);trip.isDemo=false;save();render();closeDialog();toast('Activity saved');});}
function editStopAction(type,id){const arr=currentDay().stops,i=arr.findIndex(x=>x.id===id);if(i<0)return;if(type==='edit')return editStop(id);if(type==='delete'){if(!confirm('Delete '+arr[i].name+'?'))return;arr.splice(i,1)}if(type==='up'&&i>0)[arr[i-1],arr[i]]=[arr[i],arr[i-1]];if(type==='down'&&i<arr.length-1)[arr[i],arr[i+1]]=[arr[i+1],arr[i]];save();render();}
function newTrip(){if(!confirm('Start a new trip? Your current plan stays on this device until replaced. Export it first if you want a backup.'))return;trip=demo();trip.title='My next adventure';trip.days.forEach(d=>d.stops=[]);trip.isDemo=false;chatHistory=[];chatProposals=[];save();render();openView('overview');toast('New trip created');}
function getDateParams(){return {destination:trip.destination.name,from:trip.start,to:dateAdd(trip.end,1),travelers:trip.travelers};}
function bookingProviders(category){const p=getDateParams(),d=encodeURIComponent(p.destination),from=encodeURIComponent(p.from),to=encodeURIComponent(p.to),q=encodeURIComponent(`${p.destination} ${p.from} ${p.to}`),n=p.travelers;
const groups={stays:[['Booking.com','Hotels, apartments and flexible rooms','https://www.booking.com/searchresults.html?ss='+d+'&checkin='+from+'&checkout='+to+'&group_adults='+n,'Search parameters included'],['Airbnb','Apartments and unique stays','https://www.airbnb.com/s/'+d+'/homes?checkin='+from+'&checkout='+to+'&adults='+n,'Search parameters included'],['Hotels.com','Compare hotels and reward terms','https://www.hotels.com/Hotel-Search?destination='+d,'Check dates on provider'],['Expedia','Compare stays and packages','https://www.expedia.com/Hotel-Search?destination='+d,'Check dates on provider']],flights:[['Google Flights','Compare dates, carriers and airports','https://www.google.com/travel/flights','Enter airports and dates on provider'],['Skyscanner','Compare airlines and agencies','https://www.skyscanner.com/transport/flights','Enter route and dates on provider'],['KAYAK','Search flight options and baggage terms','https://www.kayak.com/flights','Enter route and dates on provider']],activities:[['GetYourGuide','Guided tours, tickets and excursions','https://www.getyourguide.com/s/?q='+d,'Search query included'],['Viator','Tours and experiences','https://www.viator.com/searchResults/all?text='+d,'Search query included'],['Tiqets','Museums and attraction tickets','https://www.tiqets.com/en/search/?q='+d,'Check dates on provider'],['Google Maps','Local experiences and business hours','https://www.google.com/maps/search/?api=1&query='+d,'Destination included']],transport:[['Google Maps','Get walking and driving directions','https://www.google.com/maps/search/?api=1&query='+d,'Destination included'],['Rome2Rio','Research intercity connections','https://www.rome2rio.com/','Enter route on provider'],['Omio','Compare trains and buses','https://www.omio.com/','Enter route on provider'],['Rentalcars.com','Compare car rentals','https://www.rentalcars.com/','Enter dates and location on provider']]};return groups[category]||groups.stays;}
function renderBookings(){const providers=bookingProviders(activeBooking);$('#booking-grid').innerHTML=providers.map((p,i)=>`<article class="booking-card"><div class="provider-icon">${['◈','⌂','✈','↗'][i%4]}</div><strong>${esc(p[0])}</strong><p>${esc(p[1])}</p><small class="muted-text">${esc(p[3])}</small><a href="${esc(safeURL(p[2]))}" target="_blank" rel="noopener noreferrer">Search ${esc(p[0])} ↗</a></article>`).join('');$$('[data-booking]').forEach(b=>b.classList.toggle('is-active',b.dataset.booking===activeBooking));}
const guideURL=()=>`https://en.wikivoyage.org/wiki/${encodeURIComponent(trip.destination.name.split(',')[0].trim().replaceAll(' ','_'))}`;
function renderQuotes(){const quotes=[...(trip.quotes||[])].sort((a,b)=>a.price-b.price);$('#quote-list').innerHTML=quotes.length?quotes.map(q=>`<div class="quote-row"><div><strong>${esc(q.title)}</strong><small>${esc(q.provider)} · Saved ${esc(q.date||'manually')} · ${esc(q.terms||'Cancellation terms unrecorded')}</small>${q.url?`<a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">Open saved provider ↗</a>`:''}</div><div class="quote-right"><strong>${esc(money(q.price))}</strong><button data-quote-delete="${esc(q.id)}" aria-label="Remove quote">×</button></div></div>`).join(''):'<p class="muted-text">No prices saved. Search providers above, then record a quote here to compare choices.</p>';}
function renderSources(){const dest=encodeURIComponent(trip.destination.name),entries=[['Wikivoyage','Community destination guides',guideURL()],['Official tourism','Search the local tourism authority',`https://www.google.com/search?q=${encodeURIComponent(trip.destination.name+' official tourism website')}`],['Travel advisories','US Department of State',`https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories.html`],['Entry requirements','Government entry guidance',`https://www.google.com/search?q=${encodeURIComponent(trip.destination.name+' government entry visa requirements')}`],['OpenStreetMap','Community mapping and place data',`https://www.openstreetmap.org/?mlat=${trip.destination.lat}&mlon=${trip.destination.lng}#map=11/${trip.destination.lat}/${trip.destination.lng}`],['Wikimedia','Geotagged destination context',`https://en.wikipedia.org/wiki/Special:Search?search=${dest}`],['Open-Meteo','Weather forecast and climate history','https://open-meteo.com/'],['UNESCO','World heritage information','https://whc.unesco.org/en/list/'],['IATA Travel Centre','Passport, visa and health requirements','https://www.iata.org/en/services/compliance/timatic/travel-documentation'],['US travel checklist','Official international preparation guidance','https://travel.state.gov/en/international-travel/planning/checklist.html']];$('#source-grid').innerHTML=entries.map(p=>`<div class="source-card"><strong>${esc(p[0])}</strong><p>${esc(p[1])}</p><a href="${esc(safeURL(p[2]))}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div>`).join('');$('#guide-link').href=guideURL();$('#guide-heading').textContent='About '+trip.destination.name;}
async function searchDestination(q){if(!q||q.length<2){toast('Enter a city or country.');return}$('#destination-results').hidden=false;$('#destination-results').innerHTML='<div style="padding:13px;color:#83958a">Searching destinations…</div>';try{const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=8&language=en&format=json',{signal:AbortSignal.timeout(13000)});if(!r.ok)throw Error('Location provider unavailable');const list=(await r.json()).results||[];$('#destination-results').innerHTML=list.length?list.map(p=>`<button data-place-idx="${list.indexOf(p)}">${esc(p.name)}${p.admin1?', '+esc(p.admin1):''}, ${esc(p.country||'')}</button>`).join(''):'<div style="padding:13px;color:#83958a">No location found. Try a nearby large city.</div>';$('#destination-results').hidden=false;lastGeocode=list;}catch(e){$('#destination-results').innerHTML='<div style="padding:13px;color:#9e776d">Destination search unavailable right now. Retry later.</div>';lastGeocode=[];}}
function chooseDestination(i){const v=lastGeocode?.[i];if(!v)return;const previous=trip.destination.name;const keep=allStops().length?confirm('You are changing from '+previous+' to '+v.name+'. Keep the existing stops from the old destination? OK = keep; Cancel = clear those stops.'):false;if(!keep)trip.days.forEach(d=>d.stops=[]);trip.destination={name:[v.name,v.admin1,v.country].filter(Boolean).join(', '),lat:v.latitude,lng:v.longitude};trip.isDemo=false;ignoredMismatch=false;$('#destination-input').value='';$('#destination-results').hidden=true;discovered=[];guideData=null;weatherData=null;save();render();refreshGuide();refreshWeather();map?.flyTo({center:[v.longitude,v.latitude],zoom:11});toast('Destination updated · itinerary stops remain unchanged');}
function showDiscoveredStatus(s){$('#discover-status').textContent=s;}
function radiusDisplay(){const value=discoveryUnit==='mi'?discoveryRadiusKm/1.609344:discoveryRadiusKm;return `${Math.round(value)} ${discoveryUnit==='mi'?'miles':'km'}`;}
function updateRadiusUI(){const r=$('#atlas-radius');r.max=discoveryUnit==='mi'?'124':'200';r.value=Math.max(1,Math.round(discoveryUnit==='mi'?discoveryRadiusKm/1.609344:discoveryRadiusKm));$('#atlas-radius-value').textContent=radiusDisplay();$('#atlas-unit-mi').classList.toggle('is-active',discoveryUnit==='mi');$('#atlas-unit-km').classList.toggle('is-active',discoveryUnit==='km');}
function renderDiscovered(){const items=discovered;$('#atlas-result-count').textContent=`${items.length.toLocaleString()} loaded`;$('#atlas-provider-note').textContent=discoveryProvider?`${discoveryProvider} · ${radiusDisplay()} from ${trip.destination.name} · expand with Load more when available`:'No source search loaded yet.';$('#atlas-load-more').hidden=!discoveryHasMore;$('#atlas-load-more').disabled=discoveryBusy;$('#atlas-load-more').textContent=discoveryBusy?'Loading…':'Load more places ↓';
$('#discover-grid').innerHTML=items.length?items.map((p,i)=>`<article class="atlas-photo-card">
 <div class="atlas-photo-cover">${p.image?`<img loading="lazy" decoding="async" src="${esc(safeURL(p.image))}" alt="${esc(p.name)}" onerror="this.hidden=true;this.parentElement.classList.add('atlas-photo-missing')" />`:`<div class="atlas-photo-placeholder"><span>⌁</span><small>No source-verified photo available</small></div>`}<span class="atlas-distance-pill">${esc(discoveryUnit==='mi'?(p.distanceKm/1.609344).toFixed(1)+' mi':p.distanceKm.toFixed(1)+' km')}</span></div>
 <div class="atlas-photo-body"><div class="mini-label">${esc(p.source||'Place database')} · ${esc(p.category||'place')}</div><strong>${esc(p.name)}</strong><p>${esc(p.description||p.address||'Details may be incomplete; check the original provider.')}</p>${p.image&&p.creditUrl?`<a class="atlas-photo-credit" href="${esc(safeURL(p.creditUrl))}" target="_blank" rel="noopener noreferrer">Photo: ${esc(p.attribution||'Wikimedia contributor')} · ${esc(p.license||'view license')} ↗</a>`:''}<div class="atlas-card-actions"><button class="btn btn-dark" data-discover-idx="${i}">＋ Add to Day ${trip.activeDay+1}</button><a href="${esc(safeURL(p.sourceUrl||'https://www.openstreetmap.org/'))}" target="_blank" rel="noopener noreferrer">Source ↗</a></div></div>
 </article>`).join(''):'<div class="empty-state">No places found in this search. Try a larger radius or another category. Empty photo slots are not filled with unrelated stock photography.</div>';
}
async function wikiDiscoveryFallback(lat,lng,radius){const url=new URL('https://en.wikipedia.org/w/api.php');Object.entries({action:'query',generator:'geosearch',ggscoord:`${lat}|${lng}`,ggsradius:String(Math.min(10000,Math.round(radius*1000))),ggslimit:'40',prop:'coordinates|description|pageimages',piprop:'thumbnail|name',pithumbsize:'560',format:'json',origin:'*'}).forEach(([k,v])=>url.searchParams.set(k,v));const r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Wikipedia is not available.');const data=await r.json();return Object.values(data.query?.pages||{}).filter(p=>p.coordinates?.[0]).map(p=>({id:'wiki:'+p.pageid,name:p.title,lat:p.coordinates[0].lat,lng:p.coordinates[0].lon,description:p.description||'Wikipedia location · verify place type',source:'Wikipedia limited fallback',category:'sight',sourceUrl:'https://en.wikipedia.org/?curid='+p.pageid,image:safeURL(p.thumbnail?.source),creditUrl:p.pageimage?'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(p.pageimage):'',attribution:'See image credit and license',license:'See file page',distanceKm:Math.round(haversine(trip.destination,{lat:p.coordinates[0].lat,lng:p.coordinates[0].lon})*10)/10})).filter(p=>p.distanceKm<=radius).sort((a,b)=>a.distanceKm-b.distanceKm)}
async function discover(loadMore=false){if(discoveryBusy)return;discoveryBusy=true;const currentKey=`${trip.destination.lat},${trip.destination.lng}:${discoveryRadiusKm}:${discoveryCategory}`;const page=loadMore?discoveryPage:0;if(!loadMore){discovered=[];discoveryHasMore=false;discoveryPage=0;renderDiscovered();}showDiscoveredStatus(loadMore?'Loading more source records…':'Searching real places and available licensed photos…');$('#discover-refresh').disabled=true;
try{const {lat,lng}=trip.destination;const qs=new URLSearchParams({lat:String(lat),lng:String(lng),radius:String(Math.min(200,discoveryRadiusKm)),category:discoveryCategory,page:String(page)});let data;
try{const response=await fetch('/.netlify/functions/atlas-places?'+qs,{signal:AbortSignal.timeout(23000)});if(!response.ok)throw Error('Places endpoint '+response.status);data=await response.json();if(data.error)throw Error(data.error);}catch(error){if(page>0)throw Error('The paginated places service is unavailable. Upload atlas-places.mjs and configure GEOAPIFY_API_KEY for hundreds or thousands of results.');data={items:await wikiDiscoveryFallback(lat,lng,discoveryRadiusKm),next:false,limited:true,provider:'Wikipedia in-browser fallback',note:'Large-scale discovery requires the Netlify places function with a GEOAPIFY_API_KEY.'};}
if(currentKey!==`${trip.destination.lat},${trip.destination.lng}:${discoveryRadiusKm}:${discoveryCategory}`)return;
let ids=new Set(discovered.map(p=>String(p.id)));const incoming=(data.items||[]).filter(p=>!ids.has(String(p.id))&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lng))).map(p=>({...p,distanceKm:Number(p.distanceKm)||haversine(trip.destination,p)}));discovered.push(...incoming);discoveryPage=page+1;discoveryHasMore=!!data.next;discoveryProvider=data.provider||'Open data';renderDiscovered();showDiscoveredStatus(`${discovered.length.toLocaleString()} results loaded · ${radiusDisplay()} radius${data.limited?' · limited public-source sample':' · further pages may be available'}.`);if(data.note)$('#atlas-provider-note').textContent=data.note;
}catch(e){showDiscoveredStatus('Could not refresh place results: '+String(e.message||e));}finally{discoveryBusy=false;$('#discover-refresh').disabled=false;$('#atlas-load-more').disabled=false;}}
function addDiscovered(i){const p=discovered[i];if(!p)return;currentDay().stops.push({...stop(p.name,p.lat,p.lng,'10:00',p.category||'sight',75,0,'Verify opening times, access, and admission charges with the operator.'),source:p.source||'Place search',sourceUrl:safeURL(p.sourceUrl),image:safeURL(p.image),creditUrl:safeURL(p.creditUrl),attribution:plain(p.attribution,140),license:plain(p.license,70),estimate:true});save();render();toast(p.name+' added to Day '+(trip.activeDay+1));renderDiscovered();}
async function refreshGuide(){const title=trip.destination.name.split(',')[0].trim();$('#guide-summary').textContent='Checking Wikivoyage guide…';$('#guide-link').href=guideURL();try{const url='https://en.wikivoyage.org/w/api.php?action=query&prop=extracts&exintro=1&explaintext=1&format=json&origin=*&redirects=1&titles='+encodeURIComponent(title);const r=await fetch(url,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Guide unavailable');const data=await r.json();const pages=Object.values(data.query?.pages||{});const p=pages[0];if(p?.extract?.trim()){guideData=p.extract;$('#guide-summary').textContent=p.extract.slice(0,550)+(p.extract.length>550?'…':'');}else{$('#guide-summary').textContent='No short guide introduction was available through the public API. The complete Wikivoyage guide may still have useful sections—open it directly.';}}catch(e){$('#guide-summary').textContent='Could not load the guide automatically. Open the original Wikivoyage page for verified editorial context.';}}
async function refreshWeather(){const {lat,lng}=trip.destination;$('#quick-weather').textContent='Checking weather…';try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&current=temperature_2m,weather_code,wind_speed_10m&timezone=auto&forecast_days=1`;const r=await fetch(url,{signal:AbortSignal.timeout(11000)});if(!r.ok)throw Error();const j=await r.json();weatherData=j.current;const future=dateDiff(new Date().toISOString().slice(0,10),trip.start);$('#quick-weather').textContent=`${Math.round(j.current.temperature_2m)}°C · current conditions`;$('#quick-weather-detail').textContent=`Wind ${Math.round(j.current.wind_speed_10m)} km/h near ${trip.destination.name.split(',')[0]}. ${future>14?'Your trip is too far ahead for a reliable forecast.':'Check a current forecast again near travel dates.'}`;}catch{$('#quick-weather').textContent='Weather unavailable';$('#quick-weather-detail').textContent='Open-Meteo could not be reached. Try again later.';}}
function initialMap(){if(!window.maplibregl){showFallback();return;}try{map=new maplibregl.Map({container:'map',style:'https://tiles.openfreemap.org/styles/liberty',center:[trip.destination.lng,trip.destination.lat],zoom:10,attributionControl:true});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{mapReady=true;updateMap()});map.on('error',()=>{if(!mapReady)showFallback()});}catch(e){console.warn('Map unavailable',e);showFallback();}}
function showFallback(){$('#map-fallback').hidden=false;const points=allStops().filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng));const lat=[trip.destination.lat,...points.map(p=>p.lat)],lng=[trip.destination.lng,...points.map(p=>p.lng)];const bounds={minLat:Math.min(...lat),maxLat:Math.max(...lat),minLng:Math.min(...lng),maxLng:Math.max(...lng)};$('#fallback-dots').innerHTML=points.slice(0,45).map((p,i)=>{const top=clamp(50-((p.lat-trip.destination.lat)/(Math.max(.01,bounds.maxLat-bounds.minLat)))*36,8,92),left=clamp(50+((p.lng-trip.destination.lng)/(Math.max(.01,bounds.maxLng-bounds.minLng)))*36,8,92);return `<span class="fallback-pin" style="top:${top}%;left:${left}%" title="${esc(p.name)}">${i+1}</span>`}).join('');}
function updateMap(){if(!map||!mapReady){showFallback();return}$('#map-fallback').hidden=true;markers.forEach(m=>m.remove());markers=[];let points=trip.days.flatMap((d,i)=>d.stops.map(s=>({...s,day:i+1})));points.forEach((p,i)=>{const el=document.createElement('div');el.className='fallback-pin';el.style.position='static';el.title='Day '+p.day+' · '+p.name;el.textContent=String(p.day);markers.push(new maplibregl.Marker({element:el}).setLngLat([p.lng,p.lat]).setPopup(new maplibregl.Popup({offset:18}).setText(p.name)).addTo(map));});let coords=points.map(x=>[x.lng,x.lat]);try{if(map.getLayer('route-line'))map.removeLayer('route-line');if(map.getSource('route-line'))map.removeSource('route-line');if(coords.length>1){map.addSource('route-line',{type:'geojson',data:{type:'Feature',geometry:{type:'LineString',coordinates:coords}}});map.addLayer({id:'route-line',source:'route-line',type:'line',paint:{'line-color':'#e99065','line-width':3,'line-dasharray':[2,2]}})}}catch{}
$('#map-description').textContent=`${points.length} itinerary stops. Lines show straight-line connections, not travel routes.`;
$('#map-external-link').href=`https://www.openstreetmap.org/?mlat=${trip.destination.lat}&mlon=${trip.destination.lng}#map=11/${trip.destination.lat}/${trip.destination.lng}`;}
async function switchMap(kind){mapMode=kind;$$('[data-mapview]').forEach(b=>b.classList.toggle('is-active',b.dataset.mapview===kind));$('#map').hidden=kind!=='map';$('#map-fallback').hidden=kind!=='map';$('#globe-panel').hidden=kind!=='globe';if(kind==='map'){setTimeout(()=>{map?.resize();updateMap()},100);return;}if(globe){globe.update(trip);return;}if(globeBusy)return;globeBusy=true;$('#globe-render').textContent='Loading the procedural 3D Earth…';try{const mod=await import('./globe.js');globe=await mod.buildGlobe($('#globe-render'),trip);}catch(e){console.warn('3D globe unavailable',e);$('#globe-render').innerHTML='<div class="empty-state" style="color:#fff">3D requires a WebGL-enabled browser and access to Three.js. Switch to the 2D map to continue planning.</div>';}finally{globeBusy=false;}}
function exportFile(name,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
function exportTrip(){dialog('Export your trip',`<p style="color:#87998e;margin-bottom:16px;line-height:1.6">Download your itinerary as a full backup, spreadsheet, or calendar. Booking prices are not included as live quotes.</p><button class="btn btn-outline full-width" data-export="json">Download JSON backup</button><button class="btn btn-outline full-width" data-export="csv">Download Excel-compatible CSV</button><button class="btn btn-outline full-width" data-export="ics">Download calendar (.ics)</button>`);}
function doExport(type){const slug=(trip.title||'atlas-trip').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,45);if(type==='json')exportFile(slug+'.json',JSON.stringify(trip,null,2),'application/json');if(type==='csv'){const rows=[['Date','Day','Time','Place','Minutes','Estimated cost','Currency','Notes'],...trip.days.flatMap((d,i)=>d.stops.map(s=>[d.date,i+1,s.time,s.name,s.duration,s.cost,trip.currency,s.notes]))];exportFile(slug+'.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');}if(type==='ics'){const date=s=>s.replaceAll('-','');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ATLAS by Ariel Bodik//EN','CALSCALE:GREGORIAN'];trip.days.forEach(d=>d.stops.forEach(s=>{const stamp=date(d.date)+'T'+s.time.replace(':','')+'00',endDate=new Date(`${d.date}T${s.time}:00Z`);endDate.setUTCMinutes(endDate.getUTCMinutes()+s.duration);const end=endDate.toISOString().replace(/[-:]/g,'').slice(0,15);const safe=s=>String(s).replaceAll('\\','\\\\').replaceAll(/\n/g,'\\n').replaceAll(',','\\,').replaceAll(';','\\;');lines.push('BEGIN:VEVENT','UID:'+s.id+'@arielbodik.com','DTSTART:'+stamp,'DTEND:'+end,'SUMMARY:'+safe(s.name),'DESCRIPTION:'+safe('ATLAS planning placeholder; confirm local timezone. '+s.notes),'END:VEVENT');}));lines.push('END:VCALENDAR');exportFile(slug+'.ics',lines.join('\r\n'),'text/calendar');}closeDialog();toast('Trip export created');}
function toggleChat(show){$('#ai-drawer').classList.toggle('is-open',show);$('#ai-drawer').setAttribute('aria-hidden',String(!show));$('#drawer-shade').hidden=!show;if(show)setTimeout(()=>$('#chat-input').focus(),120)}
function renderChat(){const el=$('#chat-log');el.innerHTML=chatHistory.map(m=>`<div class="chat-msg ${esc(m.role)}">${esc(m.text)}</div>`).join('');el.scrollTop=el.scrollHeight;$('#chat-proposals').innerHTML=chatProposals.map((p,i)=>`<div class="proposal-card"><strong>Day ${p.day} · ${esc(p.name)}</strong><small>${esc(p.time||'09:00')} · ${esc(p.duration||60)} minutes · ${esc(money(p.cost||0))} estimate</small><button data-ai-accept="${i}">Add to itinerary</button><button class="reject" data-ai-reject="${i}">Dismiss</button></div>`).join('');}
function addChat(role,text){chatHistory.push({role,text});chatHistory=chatHistory.slice(-18);renderChat();}
async function askAI(message){const btn=$('#chat-send');if(pendingAuto||!message.trim())return;pendingAuto=true;btn.disabled=true;addChat('user',message.trim());$('#chat-input').value='';addChat('assistant','Thinking about your route…');try{const payload={message:message.trim(),history:chatHistory.slice(0,-2).slice(-10).filter(x=>x.text!=='Thinking about your route…'),trip:{title:trip.title,destination:trip.destination,from:trip.start,to:trip.end,travelers:trip.travelers,budget:trip.budget,currency:trip.currency,pace:trip.pace,days:trip.days.map((d,i)=>({day:i+1,date:d.date,stops:d.stops.map(s=>({name:s.name,lat:s.lat,lng:s.lng,time:s.time,duration:s.duration,cost:s.cost,notes:s.notes}))}))},guideExcerpt:plain(guideData,2500)};const r=await fetch('/.netlify/functions/atlas-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(55000)});let data;try{data=await r.json()}catch{throw Error('The AI function returned an unexpected response. Check Netlify function logs.')}if(!r.ok)throw Error(data.error||'AI service unavailable.');chatHistory.pop();addChat('assistant',String(data.reply||'I have no answer yet.'));chatProposals=(Array.isArray(data.proposals)?data.proposals:[]).filter(x=>x.name&&Number.isInteger(Number(x.day))&&Number(x.day)>0&&Number(x.day)<=trip.days.length&&Number.isFinite(Number(x.lat))&&Number.isFinite(Number(x.lng))&&Math.abs(Number(x.lat))<=90&&Math.abs(Number(x.lng))<=180).slice(0,12);renderChat();}catch(e){chatHistory.pop();addChat('error',`AI isn't connected: ${e.message}\n\nTo enable it, upload netlify/functions/atlas-chat.mjs and set OPENAI_API_KEY on Netlify, then redeploy. Your manual planning tools still work.`);}finally{pendingAuto=false;btn.disabled=false;}}
function acceptProposal(i){const p=chatProposals[i];if(!p)return;const d=trip.days[Number(p.day)-1];if(!d)return;d.stops.push({...stop(plain(p.name,110),Number(p.lat),Number(p.lng),/^\d\d:\d\d$/.test(p.time)?p.time:'10:00',plain(p.category,20)||'sight',clamp(p.duration||75,15,720),clamp(p.cost,0,1e7),plain(p.notes,1000)),source:'AI suggestion · unverified',estimate:true});chatProposals.splice(i,1);trip.activeDay=Number(p.day)-1;save();render();renderChat();toast('AI suggestion added to Day '+p.day+'; verify all details');}
function attachEvents(){document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view){openView(b.dataset.view);return}if(b.dataset.goto){openView(b.dataset.goto);return}if(b.dataset.day!==undefined){trip.activeDay=clamp(b.dataset.day,0,trip.days.length-1);save();render();return}if(b.dataset.pace){trip.pace=b.dataset.pace;save();renderBasics();return}if(b.dataset.mapview){switchMap(b.dataset.mapview);return}if(b.dataset.stopAction){editStopAction(b.dataset.stopAction,b.dataset.stopId);return}if(b.dataset.booking){activeBooking=b.dataset.booking;renderBookings();return}if(b.dataset.checklist){activeChecklist=b.dataset.checklist;renderChecklist();return}if(b.dataset.quoteDelete){trip.quotes=trip.quotes.filter(q=>q.id!==b.dataset.quoteDelete);save();renderQuotes();return}if(b.dataset.removeExpense){trip.expenses=trip.expenses.filter(x=>x.id!==b.dataset.removeExpense);save();renderBudget();renderOverview();return}if(b.dataset.deleteCheck){trip[activeChecklist]=trip[activeChecklist].filter(x=>x.id!==b.dataset.deleteCheck);save();renderChecklist();return}if(b.dataset.discoverIdx){addDiscovered(Number(b.dataset.discoverIdx));return}if(b.dataset.placeIdx){chooseDestination(Number(b.dataset.placeIdx));return}if(b.dataset.export){doExport(b.dataset.export);return}if(b.dataset.aiAccept!==undefined){acceptProposal(Number(b.dataset.aiAccept));return}if(b.dataset.aiReject!==undefined){chatProposals.splice(Number(b.dataset.aiReject),1);renderChat();return}if(b.dataset.prompt){toggleChat(true);askAI(b.dataset.prompt);return}});
$('#start-date').addEventListener('change',e=>updateDate('start',e.target.value));$('#end-date').addEventListener('change',e=>updateDate('end',e.target.value));$('#traveler-count').addEventListener('change',e=>{trip.travelers=clamp(e.target.value,1,25);save();renderBasics();});$('#destination-search-btn').onclick=()=>searchDestination($('#destination-input').value);$('#destination-input').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchDestination(e.currentTarget.value)}});
$('#location-warning-dismiss').onclick=()=>{ignoredMismatch=true;renderMismatch()};$('#location-warning-fix').onclick=e=>{if(e.currentTarget.dataset.fix==='kyoto'){trip.destination={name:'Kyoto, Japan',lat:35.0116,lng:135.7681};}else if(confirm('Remove activities more than 250 km from the current destination?')){trip.days.forEach(d=>d.stops=d.stops.filter(st=>haversine(trip.destination,st)<=250));}ignoredMismatch=false;save();render();map?.flyTo({center:[trip.destination.lng,trip.destination.lat],zoom:11});refreshGuide();refreshWeather();toast('Destination consistency updated')};$('#edit-name-btn').onclick=editTripName;$('#dialog-close').onclick=closeDialog;$('#dialog-backdrop').addEventListener('click',e=>{if(e.target===$('#dialog-backdrop'))closeDialog()});$('#dialog-content').addEventListener('submit',e=>{if(e.target.id==='name-form'){e.preventDefault();trip.title=plain(new FormData(e.target).get('title'),80)||'My trip';save();render();closeDialog();}});
$('#new-trip-btn').onclick=newTrip;$$('#overview-add-stop,#itinerary-add-stop,#day-add-activity').forEach(b=>b.onclick=()=>editStop(null));$('#atlas-save-option').onclick=saveCurrentOption;$('#atlas-load-preset').onclick=loadResearchIdea;
$('#atlas-option-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.optionLoad)loadSavedOption(b.dataset.optionLoad);if(b.dataset.optionDelete&&confirm('Delete this saved alternative?')){savedOptions=savedOptions.filter(x=>x.id!==b.dataset.optionDelete);optionsStore();renderOptionLab();}});
$('#manual-place-add').onclick=()=>{openView('itinerary');editStop(null)};$('#discover-refresh').onclick=()=>discover(false);$('#atlas-load-more').onclick=()=>discover(true);
$('#atlas-radius').addEventListener('input',e=>{discoveryRadiusKm=discoveryUnit==='mi'?Math.min(200,Number(e.target.value)*1.609344):Number(e.target.value);updateRadiusUI();});
$('#atlas-radius').addEventListener('change',()=>{discoveryPage=0;discoveryHasMore=false;discovered=[];renderDiscovered();showDiscoveredStatus('Radius changed. Click Find places to refresh.');});
$('#atlas-unit-mi').onclick=()=>{discoveryUnit='mi';updateRadiusUI();renderDiscovered()};$('#atlas-unit-km').onclick=()=>{discoveryUnit='km';updateRadiusUI();renderDiscovered()};
$('#atlas-category-bar').addEventListener('click',e=>{const b=e.target.closest('[data-discover-category]');if(!b)return;discoveryCategory=b.dataset.discoverCategory;$$('[data-discover-category]').forEach(el=>el.classList.toggle('is-active',el===b));discovered=[];discoveryPage=0;discoveryHasMore=false;renderDiscovered();showDiscoveredStatus('Category changed. Click Find places to refresh.');});
$('#weather-refresh-btn').onclick=refreshWeather;
$('#budget-input').addEventListener('change',e=>{trip.budget=clamp(e.target.value,0,1e8);save();renderBudget();renderOverview()});$('#currency-select').addEventListener('change',e=>{trip.currency=e.target.value;save();renderBudget();renderOverview();renderItinerary();renderBasics();toast('Currency label changed; no automatic exchange conversion')});
$('#quote-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);trip.quotes.push({id:uid(),provider:plain(f.get('provider'),55),title:plain(f.get('title'),90),price:clamp(f.get('price'),0,1e8),terms:plain(f.get('terms'),160),url:safeURL(f.get('url')),date:new Date().toISOString().slice(0,10)});e.target.reset();save();renderQuotes();toast('Quote saved · remember to recheck availability and fees')});$('#expense-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);trip.expenses.push({id:uid(),name:plain(fd.get('name'),90),category:plain(fd.get('category'),24),amount:clamp(fd.get('amount'),0,1e7)});e.target.reset();save();renderBudget();renderOverview()});$('#checklist-items').addEventListener('change',e=>{const id=e.target.dataset.check;if(id){const item=trip[activeChecklist].find(x=>x.id===id);if(item)item.done=e.target.checked;save();renderChecklist()}});$('#checklist-form').addEventListener('submit',e=>{e.preventDefault();const val=new FormData(e.target).get('name');trip[activeChecklist].push({id:uid(),name:plain(val,140),done:false});e.target.reset();save();renderChecklist()});
$('#export-btn').onclick=exportTrip;$('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>2e6)throw Error('File exceeds 2 MB.');trip=normalize(JSON.parse(await f.text()));save();render();map?.flyTo({center:[trip.destination.lng,trip.destination.lat],zoom:11});toast('Imported trip successfully');}catch(err){toast('Import failed: '+err.message);}e.target.value='';};
$$('#sidebar-ai-btn,#header-ai-btn,#floating-ai-btn,#itinerary-ai-btn').forEach(b=>b.onclick=()=>{toggleChat(true);if(b.id==='itinerary-ai-btn')$('#chat-input').value=`Suggest improvements to Day ${trip.activeDay+1} with less backtracking and adequate breaks.`;});$('#ai-close').onclick=()=>toggleChat(false);$('#drawer-shade').onclick=()=>toggleChat(false);$('#chat-form').addEventListener('submit',e=>{e.preventDefault();askAI($('#chat-input').value)});$('#chat-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleChat(false);closeDialog()}});
}
function boot(){attachEvents();updateRadiusUI();render();initialMap();refreshGuide();refreshWeather();renderChat();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
